  'steps.deformation.atNode': 'Knoten {n}',
  'steps.deformation.nodeTableCaption': 'Durchbiegung und Verdrehung an jedem Knoten.',
  'steps.deformation.stationary': 'Punkt mit waagerechter Tangente',
  'steps.deformation.stationaryCaption': 'Punkte, an denen die Verdrehung verschwindet, und die jeweilige Durchbiegung.',
  'steps.deformation.max': 'Größte Durchbiegung',
  'steps.deformation.deformedCaption': 'Biegelinie des Balkens, {f}-fach überhöht.',
