  'steps.deformation.sumFz': 'Gleichgewicht der vertikalen Kräfte',
  'steps.deformation.sumMAt': 'Momentengleichgewicht um {n}',
  'steps.deformation.segment': 'Abschnitt [m]',
  'steps.deformation.targetAuto': 'Gesucht ist die Verschiebung des Knotens {n}, der sich in der Matrizenlösung am stärksten verschiebt.',
  'steps.deformation.targetSelected': 'Gesucht ist die Verschiebung des Knotens {n}, der im Modell ausgewählt ist.',
